{
  "name": "lodash.chain",
  "description": "A powerful utility tool that enables functional programming by chaining together various methods for data manipulation and transformation, making it easier to work with complex data structures.",
  "type": "data processing",
  "functions": [
    {
      "name": "chain",
      "description": "Starts a Lodash chain, allowing for chaining of Lodash methods",
      "parameters": [
        {
          "name": "input",
          "description": "The initial input for the Lodash chain",
          "type": "any"
        }
      ],
      "returns": {
        "description": "The Lodash wrapper instance",
        "type": "LodashWrapper"
      }
    },
    {
      "name": "value",
      "description": "Extracts the value from the Lodash wrapper instance",
      "parameters": [],
      "returns": {
        "description": "The unwrapped value from the Lodash wrapper",
        "type": "any"
      }
    },
    {
      "name": "filter",
      "description": "Filters elements from the Lodash wrapper based on a given predicate",
      "parameters": [
        {
          "name": "predicate",
          "description": "The predicate function used to filter elements",
          "type": "function"
        }
      ],
      "returns": {
        "description": "The filtered Lodash wrapper",
        "type": "LodashWrapper"
      }
    },
    {
      "name": "sortBy",
      "description": "Sorts the elements of the Lodash wrapper based on a given property or function",
      "parameters": [
        {
          "name": "property",
          "description": "The property or function used to sort elements",
          "type": "string | function"
        }
      ],
      "returns": {
        "description": "The sorted Lodash wrapper",
        "type": "LodashWrapper"
      }
    },
    {
      "name": "map",
      "description": "Creates an array of values by mapping each element in the Lodash wrapper to a new value",
      "parameters": [
        {
          "name": "method",
          "description": "The method function used to map elements",
          "type": "function"
        }
      ],
      "returns": {
        "description": "The mapped Lodash wrapper",
        "type": "LodashWrapper"
      }
    }
  ]
}
